        if (action->UIActionParams.size() > 1) {
            std::list<CActionParam*>::iterator it = action->UIActionParams.end();
            CActionParamULONG* state = static_cast<CActionParamULONG*>(*--it);
            CComponent* component = static_cast<CComponent*>(*--it);
