        std::map<unsigned long, CUIState>::iterator it;
        it = map->GetStates().find(state);
        if (it != map->GetStates().end()) {
            std::map<unsigned long, CUIState> states;
            bool moved = false;
            for (it = map->GetStates().begin(); it != map->GetStates().end(); ++it) {
                if (it->first > state) {
                    std::map<unsigned long, CUIState>::value_type entry(it->first - 1, it->second);
                    states.insert(entry);
                    moved = true;
                }
                if (it->first < state)
                    states.insert(*it);
            }
            map->GetStates().clear();
            map->GetStates() = states;
            // Two whole calls, not a ternary argument: c2 hoists their identical heads above the test (0x00420EE4) as retail.
            if (moved)
                map->ChangeState(state);
            else
                map->ChangeState(state - 1);
        }
