        if (inventory && abilities) {
            if (abilities->SpellToAssign) {
                if (!AssignmentItemsExpressionsSwapping)
                    inventory->AssignThingPC(abilities->GetAbilityPDef(abilities->SpellToAssign)->ABXYPriority, slot->Value, entry);
